package entgen_test

import (
	"errors"
	"fmt"
	"log"
	"os"
	"time"

	entgen "github.com/go-sphere/entc-extensions/entcrud"
	"github.com/go-sphere/entc-extensions/entcrud/conf"
)

// User stands in for a generated ent entity.
type User struct {
	Name     string
	Birthday time.Time
}

// UserCreate stands in for the generated ent.UserCreate builder.
type UserCreate struct{}

func (c *UserCreate) SetName(string) *UserCreate        { return c }
func (c *UserCreate) SetBirthday(time.Time) *UserCreate { return c }

// UserMessage stands in for the protobuf message generated by protoc-gen-go,
// where time fields are int64 Unix seconds.
type UserMessage struct {
	Name     string
	Birthday int64
}

// This example shows how strict type checking reports a field that needs a
// custom converter. Real programs pass ent and protobuf types, as in the
// package documentation.
func ExampleBindFiles_typeMismatch() {
	dir, err := os.MkdirTemp("", "entbind")
	if err != nil {
		log.Fatal(err)
	}
	defer func() { _ = os.RemoveAll(dir) }()

	cfg := conf.NewFilesConf(dir, "entbind",
		conf.NewEntity(User{}, UserMessage{}, []any{UserCreate{}}),
	)
	err = entgen.BindFiles(cfg)

	var mismatches *conf.TypeMismatchListError
	if errors.As(err, &mismatches) {
		for _, item := range mismatches.Items {
			fmt.Printf("%s.%s: %s <- %s\n", item.Entity, item.Field, item.SourceType, item.TargetType)
			fmt.Println(item.Suggestion)
		}
	}
	// Output:
	// User.Birthday: time.Time <- int64
	// add conf.WithCustomFieldConverter(user.FieldBirthday, <converter>)
}
